import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findByEmail, isActive } from '../src/services/auth-service.js';

test('findByEmail ignores soft-deleted users', (t, done) => {
  findByEmail('alan@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});

test('isActive is true for a live user', (t, done) => {
  isActive('ada@example.com', (err, active) => {
    assert.equal(err, null);
    assert.equal(active, true);
    done();
  });
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';

test('listOrdersForUser returns only that user orders', (t, done) => {
  listOrdersForUser(1, (err, orders) => {
    assert.equal(err, null);
    assert.equal(orders.length, 2);
    assert.ok(orders.every((o) => o.user_id === 1));
    done();
  });
});

test('totalPaidCents counts only paid orders', (t, done) => {
  totalPaidCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 4200 + 9900 + 500);
    done();
  });
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findPaymentsForOrder, uncapturedTotalCents } from '../src/services/payment-service.js';

test('findPaymentsForOrder finds the payment for an order', (t, done) => {
  findPaymentsForOrder(10, (err, rows) => {
    assert.equal(err, null);
    assert.equal(rows.length, 1);
    assert.equal(rows[0].amount_cents, 4200);
    done();
  });
});

test('uncapturedTotalCents sums uncaptured payments', (t, done) => {
  uncapturedTotalCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 9900);
    done();
  });
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { UserRepository } from '../src/repositories/user-repository.js';
import { OrderRepository } from '../src/repositories/order-repository.js';

test('UserRepository.findActive matches the service behaviour', async () => {
  const users = await new UserRepository().findActive();
  assert.equal(users.length, 2);
});

test('OrderRepository.findPaid matches the service behaviour', async () => {
  const orders = await new OrderRepository().findPaid();
  assert.equal(orders.length, 3);
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listActiveUsers, findUser } from '../src/services/user-service.js';

test('listActiveUsers excludes soft-deleted users', (t, done) => {
  listActiveUsers((err, users) => {
    assert.equal(err, null);
    assert.equal(users.length, 2);
    assert.ok(users.every((u) => u.deleted_at === null));
    done();
  });
});

test('findUser returns null for an unknown id', (t, done) => {
  findUser(999, (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});

